-- Release 1.0 feature set: module gates, portal links, web database automation.
CREATE TABLE IF NOT EXISTS module_user_permissions (id INT AUTO_INCREMENT PRIMARY KEY,module_key VARCHAR(64) NOT NULL,user_id INT NOT NULL,can_access TINYINT NULL DEFAULT NULL,can_create TINYINT NULL DEFAULT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uniq_module_user (module_key, user_id),KEY idx_module_key (module_key),KEY idx_user_id (user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS portal_links (id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(120) NOT NULL,url VARCHAR(1000) NOT NULL,description TEXT NULL,icon_class VARCHAR(80) NOT NULL DEFAULT 'fas fa-link',target VARCHAR(20) NOT NULL DEFAULT '_blank',sort_order INT NOT NULL DEFAULT 0,is_active TINYINT NOT NULL DEFAULT 1,created_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_active_order (is_active, sort_order, title)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS webdatabase_auto_jobs (id INT AUTO_INCREMENT PRIMARY KEY,database_id INT NOT NULL,job_name VARCHAR(150) NOT NULL,job_type ENUM('import','export') NOT NULL,frequency ENUM('hourly','daily','weekly','monthly') NOT NULL DEFAULT 'daily',run_at TIME NOT NULL DEFAULT '09:00:00',source_path VARCHAR(1000) NULL,export_path VARCHAR(1000) NULL,field_mapping_json TEXT NULL,is_active TINYINT NOT NULL DEFAULT 1,last_run_at DATETIME NULL,next_run_at DATETIME NULL,last_status VARCHAR(20) NULL,last_message TEXT NULL,created_by INT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_due (is_active, next_run_at),KEY idx_database (database_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO settings (setting_key, setting_value, description) VALUES ('feature_schedule_enabled','1','Feature gate: schedule access'),('feature_facility_enabled','1','Feature gate: facility access'),('feature_messages_enabled','1','Feature gate: messages access'),('feature_chat_enabled','1','Feature gate: chat access'),('feature_workflow_enabled','1','Feature gate: workflow access'),('feature_task_enabled','1','Feature gate: task access'),('feature_daily_report_enabled','1','Feature gate: daily report access'),('feature_bulletin_enabled','1','Feature gate: bulletin access'),('feature_webdatabase_enabled','1','Feature gate: web database access'),('feature_address_book_enabled','1','Feature gate: address book access'),('feature_file_share_enabled','1','Feature gate: file share access'),('feature_files_enabled','1','Feature gate: file management access'),('feature_integrations_enabled','1','Feature gate: integrations access'),('feature_automation_enabled','1','Feature gate: automation access'),('feature_chat_create_roles','admin,manager,user','Roles allowed to create chat rooms'),('feature_file_share_create_roles','admin,manager,user','Roles allowed to upload shared files'),('feature_files_create_roles','admin,manager,user','Roles allowed to create folders and upload files'),('feature_webdatabase_create_roles','admin,manager,user','Roles allowed to create web databases and records'),('feature_facility_create_roles','admin,manager,user','Roles allowed to create facility reservations') ON DUPLICATE KEY UPDATE setting_value = setting_value;
INSERT INTO portal_links (title, url, description, icon_class, sort_order, is_active) SELECT '社内ポータル','https://example.com/','社内システムへの入口サンプルです。管理者が変更できます。','fas fa-building',10,1 WHERE NOT EXISTS (SELECT 1 FROM portal_links LIMIT 1);
